<div class="page-head"><div><p class="section-kicker">Module workspace</p><h1><?= e($resource['label']) ?></h1><p>Manage module records with Core’s consistent validation, filtering, pagination, and accessible controls.</p></div><a class="btn" href="<?= e_attr($basePath . $resource['route']) ?>&id=0">Add record</a></div>
<?php if ($error): ?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif; ?>
<div class="workspace-grid resource-workspace">
<section class="card"><form method="get" action="<?= e_attr($basePath . $resource['route']) ?>" class="filter-bar"><label>Search<input name="q" value="<?= e_attr($search) ?>"></label><button class="btn secondary">Search</button></form>
<?php if (!$rows): ?><div class="empty-state"><strong>No records found</strong><span>Add the first record or adjust the search.</span></div><?php else: ?><div class="table-wrap"><table><thead><tr><?php foreach($resource['columns'] as $column): ?><th><?= e($column['label']) ?></th><?php endforeach; ?><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($resource['columns'] as $column): ?><td><?= e((string)($row[$column['name']]??'—')) ?></td><?php endforeach; ?><td><a class="btn small secondary" href="<?= e_attr($basePath . $resource['route']) ?>&id=<?= (int)($row['id']??0) ?>">Edit</a></td></tr><?php endforeach; ?></tbody></table></div>
<?php $pages=max(1,(int)ceil($total/$perPage)); if($pages>1): ?><nav class="pagination" aria-label="Resource pages"><?php for($p=1;$p<=$pages;$p++): ?><a class="<?= $p===$page?'active':'' ?>" href="<?= e_attr($basePath . $resource['route']) ?>&q=<?= rawurlencode($search) ?>&page=<?= $p ?>"><?= $p ?></a><?php endfor; ?></nav><?php endif; endif; ?></section>
<section class="card"><div class="card-heading"><div><h2><?= $record?'Edit record':'Add record' ?></h2><p class="card-subtitle">Fields and persistence are defined by <?= e($resource['package']) ?>; Core supplies the workflow.</p></div></div><form method="post" action="<?= e_attr($basePath . $resource['route']) ?>"><?= $csrf->field() ?><input type="hidden" name="id" value="<?= (int)($record['id']??0) ?>"><?php foreach($resource['fields'] as $field): $name=$field['name'];$type=$field['type']??'text';$value=$record[$name]??''; ?><label><?= e($field['label']) ?><?php if($type==='textarea'): ?><textarea name="<?= e_attr($name) ?>" <?= !empty($field['required'])?'required':'' ?>><?= e((string)$value) ?></textarea><?php elseif($type==='select'): ?><select name="<?= e_attr($name) ?>" <?= !empty($field['required'])?'required':'' ?>><?php foreach((array)($field['options']??[]) as $key=>$label): ?><option value="<?= e_attr((string)$key) ?>" <?= (string)$value===(string)$key?'selected':'' ?>><?= e((string)$label) ?></option><?php endforeach; ?></select><?php elseif($type==='checkbox'): ?><span class="switch-control"><input type="checkbox" name="<?= e_attr($name) ?>" value="1" <?= !empty($value)?'checked':'' ?>><span><?= e($field['label']) ?></span></span><?php else: ?><input type="<?= e_attr($type) ?>" name="<?= e_attr($name) ?>" value="<?= e_attr((string)$value) ?>" <?= !empty($field['required'])?'required':'' ?>><?php endif; ?></label><?php endforeach; ?><div class="button-row"><button class="btn" name="action" value="save">Save record</button><?php if($record && is_callable($resource['delete'])): ?><button class="btn danger" name="action" value="delete" data-confirm="Delete this record? This cannot be undone.">Delete</button><?php endif; ?></div></form></section>
</div>
